WITH account_summary AS (SELECT account_id, COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END) AS 7_eleven_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM transactions GROUP BY account_id) SELECT a.id, a.opened_date, a.status, as.7_eleven_count, as.merchant_values FROM accounts a INNER JOIN account_summary as ON a.id = as.account_id ORDER BY opened_date DESC
